module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    wire [4:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    integer i;
    reg [4:0] expected_q;

    // Golden model function for 5-bit Galois LFSR with taps at 5 and 3 (indices 4 and 2)
    function [4:0] next_lfsr;
        input [4:0] current;
        begin
            next_lfsr = {current[0], current[4], current[3] ^ current[0], current[2], current[1] ^ current[0]};
        end
    endfunction

    initial begin
        // Initialize signals
        reset = 1;
        expected_q = 5'b00001;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        reset = 0;

        // Check reset state
        if (q !== expected_q) begin
            $display("Mismatch at reset: expected %b, got %b", expected_q, q);
            errors = errors + 1;
        end

        // Run through multiple cycles and check against golden model
        for (i = 0; i < 40; i = i + 1) begin
            @(posedge clk);
            #1; // Wait slightly past clock edge for outputs to settle
            expected_q = next_lfsr(expected_q);

            if (q !== expected_q) begin
                $display("Time %0t: Mismatch! expected %b, got %b", $time, expected_q, q);
                errors = errors + 1;
            end
        end

        // Test synchronous reset recovery
        @(posedge clk);
        reset = 1;
        expected_q = 5'b00001;
        #1;
        if (q !== expected_q) begin
            $display("Mismatch after asserting reset: expected %b, got %b", expected_q, q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        #1;
        if (q !== expected_q) begin
            $display("Mismatch immediately after deasserting reset: expected %b, got %b", expected_q, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
